import csv,json,pathlib
import urllib.request,zipfile,io
reference=pathlib.Path('work/reference-usda')
if not all((reference/name).exists() for name in ['food.csv','food_nutrient.csv','food_portion.csv']):
 reference.mkdir(parents=True,exist_ok=True)
 raw=urllib.request.urlopen('https://fdc.nal.usda.gov/fdc-datasets/FoodData_Central_sr_legacy_food_csv_2018-04.zip',timeout=60).read()
 archive=zipfile.ZipFile(io.BytesIO(raw))
 for name in archive.namelist():
  if pathlib.Path(name).name in ['food.csv','food_nutrient.csv','food_portion.csv','nutrient.csv']:(reference/pathlib.Path(name).name).write_bytes(archive.read(name))
rows={r['fdc_id']:r['description'] for r in csv.DictReader(open('work/reference-usda/food.csv',encoding='utf-8'))}
selected=[('白米饭',169757,''),('水煮意大利面',168928,'不含酱汁和额外食用油。'),('肉酱意大利面',167680,'餐厅配方参考，肉酱和用油比例会影响数值。'),('生菜',169249,'生的绿叶生菜。'),('番茄',170457,'生鲜可食部。'),('西瓜',167765,'不含瓜皮。'),('苹果',171688,'带皮可食部，不含果核。'),('水煮蛋',173424,'去壳可食部。'),('生鸡蛋',171287,'去壳可食部。'),('去皮生鸡胸肉',171077,'不含骨和皮。'),('去皮生鸡腿肉',173627,'鸡大腿肉，不含骨和皮。'),('带皮生鸡腿肉',172385,'不含骨。'),('带皮生鸡翅根',172390,'近似参考：采用鸡翅肉和皮的可食部数据，并非独立翅根测定；称重时去骨。'),('生瘦牛肉',174055,'采用牛上腰部去可分离脂肪瘦肉作为参考。'),('生牛腩',168664,'采用牛胸腹部连同可分离脂肪作为近似参考，肥瘦比例可不同。'),('生猪里脊',168249,'仅瘦肉可食部。'),('生猪梅花肉',167849,'近似参考：采用猪肩胛肉（Boston butt）连瘦肉及脂肪，中国分割方式可能不同。'),('生猪五花肉',167812,'肥瘦相间腹部肉，肥瘦比例会显著影响数值。'),('可乐',174852,'普通含糖可乐；按克重计，不直接将毫升当克。'),('麦当劳双层吉士牛肉汉堡 美版参考',172065,'参考份量：1个=155g（USDA该版本标准份量）；155g约437.1kcal。USDA美版双层吉士汉堡参考（俗称双吉），并非当前中国门店配方；中国版以官方营养和实测重量为准。'),('香蕉',173944,'去皮可食部。'),('生西兰花',170379,'生鲜可食部。'),('全脂牛奶',172217,'脂肪3.25%，未额外添加维生素A/D。'),('北豆腐',172475,'硫酸钙凝固的硬豆腐参考，品牌含水量可不同。'),('橄榄油',171413,''),('水煮土豆',170440,'去皮，无额外盐。'),('燕麦粒',169705,'干重；煮后不可直接使用此数值。'),('黄瓜',168409,'带皮生鲜。'),('生三文鱼',175167,'养殖大西洋鲑参考。')]
ids={str(i)for _,i,_ in selected};vals={i:{}for i in ids}
mapping={'1008':'calories','1003':'protein','1004':'fat','1005':'carbs','1079':'fiber','2000':'sugar','1010':'sucrose','1235':'addedSugar','1093':'sodium','1092':'potassium','1087':'calcium','1089':'iron','1090':'magnesium','1095':'zinc','1106':'vitaminA','1162':'vitaminC','1114':'vitaminD','1109':'vitaminE','1165':'vitaminB1','1166':'vitaminB2','1175':'vitaminB6','1178':'vitaminB12','1177':'folate'}
for r in csv.DictReader(open('work/reference-usda/food_nutrient.csv',encoding='utf-8')):
 if r['fdc_id'] in ids and r['nutrient_id'] in mapping:vals[r['fdc_id']][mapping[r['nutrient_id']]]=float(r['amount'])
foods=[]
for name,i,detail in selected:
 v=vals[str(i)];assert all(k in v for k in ['calories','protein','carbs','fat']),name
 foods.append(dict(name=name,weight=100,**v,reportedNutrients=list(v),presetId=f'usda-sr-{i}',sourceUrl=f'https://fdc.nal.usda.gov/food-details/{i}/nutrients',note=f'内置参考 · USDA SR Legacy 2018 · FDC {i}。每100g可食部。{detail}\n来源：{rows[str(i)]}\nhttps://fdc.nal.usda.gov/food-details/{i}/nutrients\n未报告的营养字段不计入总量，不代表实际为0。'))
# Each exercise uses adult MET tables; the gender groups are explicit reference-weight examples, not sex-specific MET claims.
activities=[('骑行','低强度',4,'01010','bicycling','休闲骑行，速度低于16km/h'),('骑行 · 16–19km/h','中等强度',6.8,'01020','bicycling','对应10–11.9英里/小时'),('骑行 · 19–22km/h','中等强度',8,'01030','bicycling','对应12–13.9英里/小时'),('骑行 · 22–26km/h','高强度',10,'01040','bicycling','对应14–15.9英里/小时'),('跑步 · 配速9分/公里','中等强度',6.5,'12028','running','约6.67km/h，取4–4.2mph档'),('跑步 · 配速8分/公里','中等强度',7.8,'12029','running','7.5km/h，取4.3–4.8mph档'),('跑步 · 配速7分/公里','高强度',8.7,'12030/12045','running','约8.57km/h，在相邻8.5与9.0 MET档之间插值的近似值'),('跑步 · 配速6分/公里','高强度',9.3,'12050','running','10km/h，取6–6.3mph档'),('跑步 · 配速5分/公里','高强度',11.8,'12080','running','12km/h，近似7.5mph档'),('跑步 · 配速4分/公里','高强度',14.8,'12115','running','15km/h，取9.3–9.6mph档'),('羽毛球','中等强度',5.5,'15030','sports','休闲单打或双打'),('羽毛球 竞技','高强度',7,'15020','sports','竞技训练'),('网球','中等强度',6.8,'15675','sports','一般中等强度'),('网球 单打','高强度',8,'15690','sports','单打'),('乒乓球','中等强度',4,'15660','sports','一般活动'),('篮球 投篮','中等强度',5,'15070','sports','投篮练习'),('篮球 比赛','高强度',8,'15040','sports','比赛'),('足球 休闲','中等强度',7,'15610','sports','休闲踢球'),('排球 休闲','低强度',3,'15720','sports','非比赛，6–9人'),('力量训练','中等强度',3.5,'02054','conditioning-exercise','多个抗阻动作，每组8–15次，含组间休息'),('力量训练','高强度',6,'02050','conditioning-exercise','高强度抗阻训练'),('椭圆机','中等强度',5,'02048','conditioning-exercise','中等用力'),('椭圆机','高强度',9,'02049','conditioning-exercise','高强度'),('划船机 低于100W','中等强度',5,'02071','conditioning-exercise','低于100瓦'),('跳绳','高强度',11,'02068','conditioning-exercise','一般连续跳绳'),('瑜伽 哈他','低强度',2.3,'02150','conditioning-exercise','哈他瑜伽'),('普拉提','低强度',2.8,'02105','conditioning-exercise','一般普拉提'),('拉伸','低强度',2.3,'02101','conditioning-exercise','轻度拉伸')]
exercises=[]
for sex,weight,label in [('male',70,'男'),('female',60,'女')]:
 for name,intensity,met,code,category,detail in activities:
  exercises.append(dict(name=name,intensity=intensity,sex=sex,caloriesPer10Minutes=round((met-1)*3.5*weight/200*10,4),referenceWeight=weight,presetId=f'compendium-2024-{sex}-{code}',sourceUrl=f'https://pacompendium.com/{category}/',note=f'内置参考 · {label}，参考体重{weight}kg。{detail}。\n2024 Adult Compendium，活动代码{code}，代谢当量 {met}。净耗能=(代谢当量−1)×3.5×参考体重÷200×10分钟；已减去1代谢当量静息耗能。\n男女使用相同活动代谢当量，数值差异来自此处的参考体重，不代表性别固定差异。其他运动不随体重自动更新，可手动修改或由实际记录更新。\nhttps://pacompendium.com/{category}/'))
pathlib.Path('electron/starter-catalog-data.mjs').write_text('// Curated public reference data. Reproduce food values with scripts/build-starter-catalog.py.\nexport const starterFoods = '+json.dumps(foods,ensure_ascii=False,indent=2)+';\nexport const starterExercises = '+json.dumps(exercises,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
print(json.dumps({'foods':len(foods),'exercises':len(exercises),'foodMacros':[(x['name'],x['calories'])for x in foods]},ensure_ascii=False))
